const CARDS=[
["Thông tin là gì?","Là những gì em biết được về người, vật và sự việc quanh mình. Ví dụ: hôm nay trời nắng.","svg0"],
["Dữ liệu là gì?","Là thông tin đã được ghi lại dưới dạng số, chữ, hình ảnh hoặc âm thanh. Ví dụ: số 30 ghi số bạn trong lớp.","svg1"],
["Em nhận thông tin bằng gì?","Bằng các giác quan: mắt nhìn, tai nghe, mũi ngửi, tay sờ. Ví dụ: mắt thấy đèn đỏ thì biết phải dừng.","svg2"],
["Dữ liệu có những dạng nào?","Chữ viết, số, hình ảnh, âm thanh, video. Ví dụ: bài hát là dữ liệu âm thanh.","svg3"],
["Vì sao cần ghi thông tin thành dữ liệu?","Để lưu lại lâu và xử lý nhanh. Ví dụ: máy tính cộng điểm cả lớp trong vài giây.","svg4"],
["Xử lý thông tin là gì?","Là nhận thông tin, biến đổi nó rồi đưa ra kết quả có ích. Ví dụ: nghe điểm các môn rồi tính điểm trung bình.","svg5"],
["4 bước xử lý thông tin là gì?","Thu nhận, xử lý, lưu trữ và truyền thông tin.","svg6"],
["Lưu trữ thông tin là gì?","Là cất giữ thông tin để dùng lại sau. Ví dụ: ghi điểm vào sổ, lưu bài vào máy tính.","svg7"],
["Truyền thông tin là gì?","Là gửi thông tin cho người khác. Ví dụ: nói cho mẹ biết điểm, gửi tin nhắn cho bạn.","svg8"],
["Máy tính khác con người ở điểm nào khi xử lý thông tin?","Máy tính xử lý bằng bộ xử lý theo chương trình; con người xử lý bằng não.","svg9"],
["Bit là gì?","Là đơn vị nhỏ nhất của thông tin trong máy tính, chỉ nhận 2 giá trị 0 hoặc 1.","svg10"],
["Byte là gì?","Là nhóm 8 bit, dùng làm đơn vị đo lượng thông tin thường gặp.","svg11"],
["Vì sao máy tính dùng dãy 0 và 1?","Vì mạch điện tử chỉ phân biệt được 2 trạng thái có điện và không có điện.","svg12"],
["Một bài hát và một bộ phim, cái nào thường nặng hơn?","Bộ phim nặng hơn: bài hát khoảng vài MB, phim khoảng vài GB.","svg13"],
["Khi mở ảnh, máy tính làm gì?","Máy đổi dãy bit đã lưu thành hình ảnh cho em nhìn thấy.","svg14"],
["Mạng máy tính là gì?","Là các máy tính và thiết bị nối với nhau để chia sẻ dữ liệu và dùng chung thiết bị.","svg15"],
["Nêu 2 lợi ích của mạng máy tính.","Dùng chung thiết bị, dữ liệu và liên lạc nhanh giữa mọi người.","svg16"],
["Mạng LAN là gì?","Là mạng nhỏ trong một phòng, một nhà, một trường. Ví dụ: mạng phòng máy của trường.","svg17"],
["Mạng WAN là gì?","Là mạng nối nhiều mạng nhỏ ở xa nhau, như giữa các tỉnh, các nước.","svg18"],
["Vì sao vi-rút nguy hiểm với mạng máy tính?","Vì vi-rút ở một máy có thể lan sang máy khác qua mạng.","svg19"],
["Internet là gì?","Là mạng máy tính toàn cầu, nối hàng tỉ thiết bị trên khắp thế giới với nhau.","svg20"],
["Muốn lên mạng cần những gì?","Thiết bị (máy tính hoặc điện thoại), đường truyền (Wi-Fi hoặc 4G) và nhà cung cấp dịch vụ.","svg21"],
["Website là gì?","Là một trang thông tin trên Internet, mỗi trang có địa chỉ riêng.","svg22"],
["Trình duyệt web dùng để làm gì?","Để mở các website. Ví dụ: Chrome, Cốc Cốc, Edge.","svg23"],
["Vì sao không nên tin ngay mọi thông tin trên mạng?","Vì có cả tin giả. Em phải kiểm tra nguồn trước khi tin.","svg24"],
["Mạng thông tin toàn cầu (Web) là gì?","Là hệ thống các trang web liên kết với nhau trên Internet.","svg25"],
["Địa chỉ web (URL) dùng để làm gì?","Là địa chỉ riêng của mỗi trang, giúp trình duyệt tìm đúng trang.","svg26"],
["Liên kết (link) là gì?","Là chữ hoặc hình bấm vào để nhảy sang trang khác.","svg27"],
["Web khác Internet thế nào?","Internet là mạng (đường đi); Web là dịch vụ chạy trên Internet (các trang web).","svg28"],
["Muốn xem Web, em cần làm gì?","Mở trình duyệt web rồi gõ địa chỉ trang hoặc bấm vào liên kết.","svg29"],
["Công cụ tìm kiếm là gì?","Là trang web giúp em tìm các trang khác theo từ khóa. Ví dụ: Google.","svg30"],
["Từ khóa là gì?","Là từ hoặc cụm từ mô tả điều em cần tìm. Ví dụ: muốn tìm về sao Hỏa thì gõ “sao Hỏa”.","svg31"],
["Vì sao nên dùng từ khóa cụ thể?","Vì từ khóa càng cụ thể, kết quả càng đúng ý em.","svg32"],
["Tìm chưa ra thì làm gì?","Thử đổi từ khóa khác cùng nghĩa.","svg33"],
["Đánh giá kết quả tìm kiếm bằng cách nào?","Xem trang có đáng tin không, ai viết, đăng từ khi nào, và đối chiếu thêm 1-2 nguồn khác.","svg34"],
["Thư điện tử là gì?","Là thư gửi qua mạng Internet, đến nơi gần như ngay lập tức.","svg35"],
["Địa chỉ email gồm những phần nào?","Phần trước dấu @ là tên hộp thư của em, phần sau dấu @ là tên nhà cung cấp dịch vụ.","svg36"],
["Thư nháp là gì?","Là thư em viết dở, chưa gửi, máy lưu lại để em viết tiếp sau.","svg37"],
["Gửi thư điện tử gồm mấy bước?","3 bước: nhập địa chỉ người nhận, viết tiêu đề và nội dung, rồi bấm Gửi.","svg38"],
["Vì sao phải cẩn thận với thư lạ?","Vì thư lạ có thể chứa vi-rút hoặc link lừa đảo.","svg39"],
["Thông tin cá nhân là gì?","Là thông tin riêng của em: họ tên, tuổi, địa chỉ nhà, số điện thoại, mật khẩu, hình ảnh riêng tư.","svg40"],
["Mật khẩu mạnh là mật khẩu thế nào?","Dài, gồm chữ hoa, chữ thường, số và ký tự đặc biệt. Ví dụ: “Mai@2026Hoc” mạnh hơn “123456”.","svg41"],
["Gặp tin nhắn trúng thưởng kèm link, em làm gì?","Không bấm link, không nhập mật khẩu, không gửi tiền, báo ngay cho người lớn.","svg42"],
["Bị bắt nạt qua mạng, em làm gì?","Không đáp trả, lưu lại bằng chứng và báo thầy cô hoặc người lớn.","svg43"],
["Dùng mạng có văn hóa là thế nào?","Không nói xấu, không chia sẻ tin chưa kiểm chứng, không xem nội dung không phù hợp lứa tuổi.","svg44"],
["Sơ đồ tư duy là gì?","Là cách trình bày ý tưởng bằng hình ảnh: ý chính ở giữa, các ý nhỏ tỏa ra xung quanh bằng nhánh.","svg45"],
["Sơ đồ tư duy giúp gì cho việc học?","Giúp nhìn thấy toàn bộ bài trong một hình, nhớ nhanh và sắp xếp ý rõ ràng.","svg46"],
["Mỗi nhánh trong sơ đồ ghi gì?","Một ý, bằng từ ngắn gọn, không viết cả đoạn dài.","svg47"],
["Vì sao nên dùng màu sắc và hình vẽ trong sơ đồ?","Vì màu và hình giúp não nhớ tốt hơn và phân biệt các nhánh nhanh hơn.","svg48"],
["Vẽ sơ đồ bằng phần mềm có lợi gì?","Vẽ đẹp, sửa dễ, lưu lại và chia sẻ cho bạn được.","svg49"],
["Định dạng văn bản là gì?","Là thay đổi hình thức trình bày của chữ và đoạn văn để văn bản rõ ràng, dễ đọc và đẹp hơn.","svg50"],
["Phông chữ và cỡ chữ là gì?","Phông chữ là kiểu chữ, ví dụ Times New Roman; cỡ chữ là độ to nhỏ của chữ, đo bằng pt.","svg51"],
["In đậm dùng để làm gì?","Để nhấn mạnh ý quan trọng. Ví dụ: tiêu đề bài văn in đậm.","svg52"],
["In nghiêng dùng cho trường hợp nào?","Cho tên sách, tên bài hát hoặc từ nước ngoài.","svg53"],
["Căn lề có những kiểu nào?","Căn trái, căn giữa, căn phải và căn đều hai bên.","svg54"],
["Bảng gồm những gì?","Gồm hàng (xếp ngang) và cột (xếp dọc); chỗ hàng gặp cột gọi là ô.","svg55"],
["Ô trong bảng là gì?","Là chỗ hàng gặp cột, mỗi ô chứa một thông tin.","svg56"],
["Dạng bảng tiện ở điểm nào?","Giúp so sánh và tra cứu nhanh. Ví dụ: dò đúng hàng và cột là thấy môn học.","svg57"],
["Hàng tiêu đề thường trình bày thế nào?","In đậm và căn giữa để người đọc biết mỗi cột là gì.","svg58"],
["Khi nào nên dùng bảng, khi nào nên dùng đoạn văn?","So sánh nhiều mục thì dùng bảng; kể chuyện, giải thích dài thì dùng đoạn văn.","svg59"],
["Tìm kiếm (Find) là gì?","Là lệnh giúp tìm nhanh một từ trong văn bản dài. Ví dụ: bấm Ctrl+F, gõ “trường”, máy chỉ ngay mọi chỗ có từ đó.","svg60"],
["Thay thế (Replace) là gì?","Là lệnh đổi từ cũ thành từ mới. Ví dụ: đổi từ sai “truờng” thành “trường”.","svg61"],
["Thay thế khác Thay tất cả ở điểm nào?","Thay thế chỉ đổi một chỗ đang xem; Thay tất cả đổi mọi chỗ có từ đó trong cả bài.","svg62"],
["Vì sao sau khi Thay tất cả phải đọc lại bài?","Vì nó đổi mọi chỗ có từ đó, kể cả chỗ em không muốn đổi.","svg63"],
["Phím tắt mở Tìm kiếm là gì?","Ctrl+F.","svg64"],
["Sổ lưu niệm là gì?","Là cuốn sổ ghi lại kỷ niệm của lớp: ảnh chụp, lời nhắn, những chuyện vui cả năm.","svg65"],
["Hoàn thiện sổ lưu niệm gồm những bước nào?","Thu thập nội dung; sắp xếp; định dạng văn bản; chèn ảnh và bảng; kiểm tra chính tả; lưu và chia sẻ.","svg66"],
["Sắp xếp nội dung theo gì thì dễ theo dõi?","Theo chủ đề hoặc trình tự thời gian. Ví dụ: “Đầu năm”, “Dã ngoại”, “Cuối năm”.","svg67"],
["Làm sổ theo nhóm cần phân công thế nào?","Rõ ai thu thập ảnh, ai viết lời, ai trình bày, theo sở trường của từng bạn.","svg68"],
["Trước khi lưu và chia sẻ sổ, em phải làm gì?","Đọc lại để sửa lỗi chính tả và xem ảnh có đúng chỗ không.","svg69"],
["Thuật toán là gì?","Là dãy các bước làm việc theo thứ tự để giải quyết một việc. Ví dụ: các bước pha trà sữa.","svg70"],
["Thuật toán tốt cần những tính chất nào?","Rõ ràng, đúng thứ tự và kết thúc.","svg71"],
["Vì sao không được đổi thứ tự các bước?","Vì đổi thứ tự thì việc có thể hỏng. Ví dụ: chưa cho trà mà đã khuấy thì không thành trà sữa.","svg72"],
["Thuật toán mô tả bằng những cách nào?","Bằng lời (liệt kê các bước) hoặc bằng sơ đồ khối (vẽ các bước nối bằng mũi tên).","svg73"],
["Máy tính có tự nghĩ ra thuật toán không?","Không, máy chỉ làm theo thuật toán con người viết ra.","svg74"],
["Cấu trúc tuần tự là gì?","Là các lệnh chạy lần lượt từ trên xuống dưới, lệnh nào trước làm trước.","svg75"],
["Cấu trúc rẽ nhánh là gì?","Là: nếu điều kiện đúng thì làm việc này, nếu sai thì làm việc khác.","svg76"],
["Điều kiện là gì?","Là câu hỏi chỉ có đúng hoặc sai. Ví dụ: “Trời có mưa không?”","svg77"],
["Cấu trúc lặp là gì?","Là lặp lại một việc nhiều lần. Ví dụ: đọc 10 trang sách mỗi ngày trong 7 ngày.","svg78"],
["Ba cấu trúc kết hợp để làm gì?","Để viết chương trình giải quyết việc phức tạp.","svg79"],
["Chương trình máy tính là gì?","Là tập hợp các lệnh viết bằng ngôn ngữ lập trình để máy thực hiện một việc.","svg80"],
["Ngôn ngữ lập trình là gì?","Là ngôn ngữ để con người viết lệnh cho máy hiểu. Ví dụ: Scratch dùng khối lệnh kéo thả.","svg81"],
["Lập trình là gì?","Là việc viết chương trình. Người viết lệnh, máy làm theo từng lệnh.","svg82"],
["Chương trình chạy theo những bước nào?","Nhập dữ liệu, xử lý, xuất kết quả.","svg83"],
["Gỡ lỗi là gì?","Là chạy thử, tìm lỗi và sửa lỗi khi chương trình chạy sai.","svg84"]
];
